// -----------------------------------------------------------------------------
// LBEGDataSource.cs
// -----------------------------------------------------------------------------
// Implements the IBovisDataSource interface for the LBEG database. Handles
// connection lifecycle, schema loading, and provides query methods for borehole
// (Stamm) information, sample identifiers, and record counts. Includes utility
// classes and constants used throughout the data‑access layer.
// -----------------------------------------------------------------------------
using Bovis.Interfaces;
using Bovis.Interfaces.Configuration;
using Dapper;
using DbTools;
using DbTools.DbUrl;
using System;
using System.Data;
using System.Data.Common;
using System.Numerics;
using System.Security.Cryptography;
using System.Text;
using static System.Runtime.InteropServices.JavaScript.JSType;

namespace Bovis.Data.LBEG
{
    /// <summary>
    /// Holds constant values that are shared across the LBEG data‑access layer,
    /// such as table names and column lists.
    /// </summary>
    internal class Globals
    {
        /// <summary>
        /// Name of the primary "Stamm" (borehole) table.
        /// </summary>
        public const string StammTableName = "GEHYFR_LOC_S3STAMM";

        // Usable fields in the Stamm table. TODO: Problem is geom here. This should be handled with a dapper type handler; 
        /// <summary>
        /// Comma‑separated list of fields that are selected from the Stamm table.
        /// </summary>
        public const string StammTableFields= "PRJ_ID, LOCID, RECID, XCOORD, YCOORD, ZCOORDB, ZCOORDE, SHORTNAME, LONGNAME, BID, TK25, TK5, ARFACH, ARNUM, AKBEZ, ANAME, ORTSBEZ, GEMEINDE, LKREIS, KFIND, KSYS, HFIND, HSYS, ENDHORIZ, BART, BVER, BZEITA, BZEITE, AUTOR, DATUM, ERFDATUM, ERFNAME, PROJEKT, AUFGEB, BFIRMA, BZW, DATHINW, GRUNDWASS, AUSBAUDAT, TITELDATEN, PROFILTYP, LOGMESS, ARCHIVDAT, PROBENDAT, SCHICHTDAT, MESSDATEN, VERTR, NOTIZSTM, UP_DATE, OST, NORD, ZCOORDEF, FREIGABE, BOHRANZEIGE, BUNDESLAND, BESCHEID, BESCHEID_DATUM, LEGENDE, LEGENDE_I";

        /// <summary>
        /// Name of the table that stores layer (Schicht) information.
        /// </summary>
        public const string SchichtTableName = "BOVIS_SCHICHTEN";
    }

    /// <summary>
    /// Implementation of <see cref="IBovisDataSource"/> for the LBEG database.
    /// Manages connection lifecycle, initialization of measurement procedures,
    /// and provides methods to query borehole data.
    /// </summary>
    public class LBEGDataSource : BovisSqlDataSourceBase, IBovisDataSource, IDisposable
    {
        /// <summary>
        /// Gets the collection of measurement procedures (Messverfahren) available.
        /// The measurements are taken from the internal mapping defined in <see cref="LBEGMeasurementMethods.MeasurementTypeMap"/>.
        /// </summary>
        public IEnumerable<IBovisDataSource.Verfahren> Messverfahren
        {
            get
            {
                foreach (var k in LBEGMeasurementMethods.MeasurementTypeMap)
                {                     
                    yield return new IBovisDataSource.Verfahren
                    {
                        ID = k.Key,
                        Name = $"{k.Value} ({k.Key})"
                    };
                }
            }
        }

        // LBEG has not short codes to decode.
        // IKuerzelDecoder? m_decoder;

        private readonly DbConnection m_conn;
        private bool m_isOpen = false;
        readonly private string? m_initString = null;
        private readonly object m_openLock = new();
        private bool m_disposedValue;
        private readonly IConfigurationStore m_configDb;

        /// <summary>
        /// Return the underlying <see cref="DbConnection"/> used by this data source. This connection is managed internally and should not be disposed by external code.
        /// </summary>
        public IDbConnection Connection => m_conn;

        /// <summary>
        /// Initializes a new instance of <see cref="LBEGDataSource"/> using a
        /// <see cref="ConnectionUrl"/> to create the underlying <see cref="DbConnection"/>.
        /// </summary>
        /// <param name="url">The connection URL describing how to connect to the database.</param>
        /// <param name="config">Configuration store used for auxiliary data.</param>
        /// <param name="dataInit">Optional SQL script executed after opening the connection.</param>
        public LBEGDataSource(ConnectionUrl url, IConfigurationStore config, string? dataInit = null)
        {
            m_conn = url.CreateConnection();
            m_configDb = config;
            m_initString = dataInit;
            LoadSchemasFromAssets("Bovis.Data.LBEG/schema.yaml");
        }

        /// <summary>
        /// Initializes a new instance of <see cref="LBEGDataSource"/> with an existing
        /// <see cref="DbConnection"/>.
        /// </summary>
        /// <param name="conn">An already created database connection.</param>
        /// <param name="config">Configuration store used for auxiliary data.</param>
        /// <param name="dataInit">Optional SQL script executed after opening the connection.</param>
        public LBEGDataSource(DbConnection conn, IConfigurationStore config, string? dataInit = null)
        {
            m_conn = conn;
            m_configDb = config;
            m_initString = dataInit;
            LoadSchemasFromAssets("Bovis.Data.LBEG/schema.yaml");
        }

        /// <summary>
        /// Opens the connection to the data source and initializes the necessary components
        /// of the <see cref="LBEGDataSource"/>.
        /// </summary>
        /// <remarks>
        /// Opens the database connection in a scoped lock, initializes the short code decoders,
        /// and preloads measurement procedure tables.
        /// </remarks>
        public void Open()
        {
            // Double‑check lock pattern ensures thread‑safe lazy initialization.
            if (m_isOpen) return;
            lock (m_openLock)
            {
                if (m_isOpen) return;

                // Open the underlying DB connection.
                m_conn.Open();

                // Execute optional initialization SQL if provided.
                if (m_initString != null)
                    m_conn.Execute(m_initString);
                m_isOpen = true;
            }
        }

        /// <summary>
        /// Asynchronous counterpart of <see cref="Open"/>. Currently performs the
        /// synchronous open operation and returns a completed task.
        /// </summary>
        public async Task OpenAsync()
        {
            Open();
